// Optional media CDN base. Empty = same-origin (here.now / local).
// Generated by scripts/apply-media-cdn.mjs — do not hand-edit the constant.
export const MEDIA_CDN_BASE = "";

/** @param {string} relative path like ./assets/foo.webp or assets/foo.webp or foo.webp under assets */
export function assetUrl(relative) {
  const cleaned = String(relative || '').replace(/^\.\//, '');
  const path = cleaned.startsWith('assets/') ? cleaned : ('assets/' + cleaned);
  if (!MEDIA_CDN_BASE) return "./" + path;
  return MEDIA_CDN_BASE.replace(/\/$/, '') + '/' + path;
}
